<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$u=current_user();$q=db()->prepare('SELECT ROUND(100*SUM(a.status="Present")/NULLIF(COUNT(*),0),2) pct,s.name FROM attendance a JOIN students st ON st.id=a.student_id JOIN attendance_sessions ss ON ss.id=a.session_id JOIN subjects s ON s.id=ss.subject_id WHERE st.user_id=? GROUP BY s.id,s.name ORDER BY s.name');$q->execute([$u['id']]);page_top('Attendance Intelligence');?><div class='card p-4'><table class='table'><tr><th>Subject</th><th>Attendance</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['name'])?></td><td><div class='progress'><div class='progress-bar' style='width:<?=min(100,(float)$r['pct'])?>%'><?=e($r['pct'])?>%</div></div></td></tr><?php endforeach;?></table><div class='alert alert-warning'>Attendance below the configured threshold triggers notifications.</div></div><?php page_bottom();